import React, { useState } from "react";
import { useHistory } from "react-router-dom";
import { Container, Card } from "react-bootstrap";
import Navbar from "../../components/Navbar";
import Sidebar from "../../components/Sidebar";
import { withdraw } from "../../api/bankingApi";
import { getAccountId } from "../../utils/auth";

const QUICK_AMOUNTS = [500, 1000, 2000, 5000];

function Withdraw({ onSuccess, onCancel }) {
  const history = useHistory();
  const standalone = typeof onSuccess !== "function";

  const [amount, setAmount] = useState("");
  const [message, setMessage] = useState("");
  const [loading, setLoading] = useState(false);

  const handleSuccess = (msg) => {
    if (standalone) {
      history.push("/dashboard");
    } else {
      onSuccess(msg);
    }
  };

  const handleCancel = () => {
    if (standalone) {
      history.push("/dashboard");
    } else {
      onCancel();
    }
  };

  const handleWithdraw = async () => {
    if (!amount || parseFloat(amount) <= 0) {
      setMessage("Please enter a valid withdrawal amount.");
      return;
    }
    setLoading(true);
    try {
      await withdraw({
        accountId: parseInt(getAccountId(), 10),
        amount: parseFloat(amount),
      });
      localStorage.setItem("refreshDashboard", "true");
      setAmount("");
      setMessage("");
      handleSuccess("Withdrawal successful!");
    } catch (error) {
      console.error("Withdrawal error:", error);
      setMessage("Withdrawal failed. Please try again.");
    }
    setLoading(false);
  };

  const form = (
    <div>
      <div className="d-flex flex-column align-items-center text-center mb-4">
        <span
          className="d-flex align-items-center justify-content-center rounded-circle mb-2"
          style={{ width: 56, height: 56, background: "linear-gradient(135deg,#e11d48,#9f1239)", boxShadow: "0 8px 20px rgba(225,29,72,0.3)" }}
        >
          <i className="bi bi-arrow-up-circle text-white" style={{ fontSize: 24 }}></i>
        </span>
        <div className="fw-bold" style={{ fontSize: 15 }}>Withdraw Money</div>
        <div className="text-muted" style={{ fontSize: 12 }}>Funds are deducted from your active account</div>
      </div>

      {message && (
        <div className="usr-alert usr-alert-danger" style={{ marginBottom: 16 }}>
          {message}
        </div>
      )}

      <div style={{ marginBottom: 12 }}>
        <label style={{ fontSize: 12, fontWeight: 600, color: "#64748b", textTransform: "uppercase", letterSpacing: "0.5px", display: "block", marginBottom: 6 }}>
          Amount
        </label>
        <div
          className="d-flex align-items-center"
          style={{ border: "1.5px solid #e2e8f0", borderRadius: 12, padding: "6px 14px", background: "#fafbfe" }}
        >
          <span className="fw-bold me-2" style={{ fontSize: 22, color: "#e11d48" }}>₹</span>
          <input
            type="number"
            min="0.01"
            step="0.01"
            placeholder="0.00"
            value={amount}
            onChange={(e) => setAmount(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && handleWithdraw()}
            style={{
              width: "100%", border: "none", background: "transparent", outline: "none",
              fontSize: 22, fontWeight: 700, color: "#0f172a", fontFamily: "Inter, sans-serif",
            }}
          />
        </div>
      </div>

      <div className="d-flex gap-2 flex-wrap" style={{ marginBottom: 20 }}>
        {QUICK_AMOUNTS.map((amt) => (
          <button
            key={amt}
            onClick={() => setAmount(String(amt))}
            style={{
              padding: "6px 14px", borderRadius: 100, fontSize: 12.5, fontWeight: 600,
              border: String(amt) === amount ? "1.5px solid #e11d48" : "1.5px solid #e2e8f0",
              background: String(amt) === amount ? "#ffe4e6" : "#fff",
              color: String(amt) === amount ? "#9f1239" : "#64748b",
              cursor: "pointer", fontFamily: "Inter, sans-serif",
            }}
          >
            ₹{amt.toLocaleString("en-IN")}
          </button>
        ))}
      </div>

      <div style={{ display: "flex", gap: 10 }}>
        <button
          onClick={handleWithdraw}
          disabled={!amount || loading}
          style={{
            flex: 1, padding: "12px", borderRadius: 12, border: "none",
            background: loading ? "#fda4af" : "linear-gradient(135deg,#e11d48,#9f1239)",
            color: "#fff", fontSize: 14.5, fontWeight: 700, cursor: loading ? "not-allowed" : "pointer",
            fontFamily: "Inter, sans-serif", boxShadow: loading ? "none" : "0 6px 16px rgba(225,29,72,0.3)",
          }}
        >
          {loading ? "Processing…" : "Confirm Withdrawal"}
        </button>
        <button
          onClick={handleCancel}
          style={{
            padding: "12px 18px", borderRadius: 12, border: "1.5px solid #e2e8f0",
            background: "transparent", color: "#64748b", fontSize: 14,
            fontWeight: 600, cursor: "pointer", fontFamily: "Inter, sans-serif",
          }}
        >
          Cancel
        </button>
      </div>
    </div>
  );

  if (!standalone) {
    return form;
  }

  return (
    <div>
      <Navbar />
      <div className="d-flex">
        <Sidebar />
        <Container fluid className="p-4 p-md-5 d-flex justify-content-center">
          <Card className="border-0 shadow-sm nb-shadow-soft" style={{ maxWidth: 480, width: "100%", height: "fit-content" }}>
            <Card.Body className="p-4 p-md-5">
              {form}
            </Card.Body>
          </Card>
        </Container>
      </div>
    </div>
  );
}

export default Withdraw;
